var items = $input.all();
var staticData = $getWorkflowStaticData('global');
if (!staticData.processedUrls) staticData.processedUrls = [];

var sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

var fresh = items.filter(function(item) {
  var url = item.json.link || item.json.guid || '';
  var pubDate = new Date(item.json.pubDate || item.json.isoDate || 0);
  return pubDate > sevenDaysAgo && !staticData.processedUrls.includes(url);
});

if (fresh.length === 0) {
  return [{ json: { skip: true, reason: 'No new items this week' } }];
}

// Carousel'da en fazla 10 slide göster (LinkedIn document post sweet spot)
var picked = fresh.slice(0, 10);

picked.forEach(function(item) {
  var url = item.json.link || item.json.guid || '';
  if (url) staticData.processedUrls.push(url);
});
if (staticData.processedUrls.length > 200) {
  staticData.processedUrls = staticData.processedUrls.slice(-200);
}

// Hafta aralığı (Apr 14 — Apr 21, 2026 formatı)
function fmt(d) {
  var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return months[d.getUTCMonth()] + ' ' + d.getUTCDate();
}
var now = new Date();
var start = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
var weekRange = fmt(start) + ' — ' + fmt(now) + ', ' + now.getUTCFullYear();

var entries = picked.map(function(item, i) {
  var title = (item.json.title || '').trim();
  var summary = (item.json.contentSnippet || item.json.content || item.json.summary || '')
    .replace(/<[^>]*>/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 320);
  return (i + 1) + '. ' + title + '
   ' + summary;
}).join('

');

var prompt = "You are a senior Shopify developer with years of production experience, writing a weekly LinkedIn carousel for your peers. The carousel is a swipeable PDF: cover → one slide per update → closing senior take → outro. Your job is to produce the slide content AND the short LinkedIn caption that accompanies the carousel.

Shopify shipped these updates in the past 7 days:

" + entries + "

Return STRICT JSON ONLY (no prose, no markdown fences, no comments). Schema:
{
  "weekRange": string,            // exactly: "" + weekRange + ""
  "slides": [
    { "emoji": string, "title": string, "body": string }
  ],
  "closing": string,              // senior take, 1–2 sentences
  "linkedinCaption": string       // short text shown above the carousel
}

Rules for `slides` (one per Shopify update, in the same order as listed above):
- `title`: rewrite the update name in clean Title Case, max 56 characters. Keep Shopify product names untranslated (Shopify Flow, Shopify Functions, Shop Pay, Shopify Markets, Shopify Plus, Shopify Payments, Shopify Inbox, Sign in with Shop, ShopifyQL).
- `body`: TWO sentences, 45–75 words total (~280–480 characters). Carousel slides have plenty of vertical space; do NOT cut content short. Anything under 220 characters fails the format.
  Sentence 1 = what the update actually changes, in your own words, NOT a paraphrased title.
  Sentence 2 = who benefits and in which concrete scenario, OR what real developer/merchant pain it removes. Must contain at least one specific, technical or operational detail (Liquid limitation, metaobject/metafield pattern, checkout extension or Function use case, B2B catalog scenario, multi-location inventory ops, theme architecture pain, OS 2.0 patterns, performance/CLS impact, app integration headache, store profile like subscription / high-SKU / multi-currency / POS-heavy).
  Frame as a SCENARIO, not a fake personal accomplishment.
- `emoji`: ONE single emoji per slide. EVERY slide must use a DIFFERENT emoji. Pick from this mapping (use the closest match, use the second alternative if the first is already taken in this carousel):
  Checkout / Shop Pay: 🛒 or 💳
  Payments: 💳 or 💰
  Analytics / Reports / Insights: 📊 or 📈
  Themes / Liquid / Online Store: 🎨 or 🧱
  Apps / App Bridge: 🧩
  Functions / Scripts / Flow: ⚙️ or 🔧
  Inventory / Locations / Fulfillment: 📦 or 🚚
  B2B / Plus: 🏢
  Markets / international: 🌍
  POS: 🏪
  Customer accounts / Sign in with Shop: 👤
  Discounts: 🏷️
  AI / Sidekick: 🤖
  Search / discovery: 🔍
  Email / Inbox: 📧 or 💬
  Performance / speed: ⚡
  Security / fraud: 🔐
  Subscriptions: 🔁
  Developer tooling / CLI / GraphQL / APIs: 🛠️
  Mobile / Shop app: 📱

Rules for `closing`:
- 30–60 words (~200–400 characters). ONE focused observation about Shopify's direction this week, an edge case worth flagging, OR how a few of the updates fit together. Anything under 180 characters fails the format. No personal autobiographical claims. No 'this makes my X obsolete', no 'good thing for merchants', no cheerleading.
- Plain text (the carousel template adds the giant "" quote mark on its own).

Rules for `linkedinCaption` (this is the text that appears ABOVE the carousel in the LinkedIn feed):
- 400–700 characters total. Anything under 350 characters fails the format.
- Required structure (each separated by ONE blank line):
  Line 1: ONE emoji + a sharp hook (a question, a bold claim, or a crisp framing). 8–16 words.
  Block 2: 2–3 short sentences explaining what is in the carousel, what kind of developer/merchant it is for, and one concrete topic readers will get out of it. Drop ONE specific term from the slides (analytics, checkout extensibility, B2B, Functions, etc.) so it is not generic.
  Block 3: ONE call-to-action line ("Swipe through the carousel" or "Open the carousel for the full breakdown"). Mention the week range.
  Last three lines exactly: a blank line, then `Powered by Checkpoint: Store Scanner`, then on the next line `#Shopify #ShopifyDev #ShopifyChangelog #Ecommerce`.
- DO NOT repeat the slide bodies verbatim; the caption is a teaser, not a recap.
- DO NOT use generic openers like "What's new in Shopify this week?" — too predictable. Make it sharper.

BANNED words and phrases everywhere (caption, slides, closing): exciting, excited, game-changing, massive, huge, awesome, amazing, revolutionary, empower, empowers, supercharge, seamless, seamlessly, robust, cutting-edge, next-level, leverage, ecosystem, at scale, love to see, thrilled, proud to share, can't wait, dive in, level up, take your store to, unlock (as a hype noun — verb form is fine in a use case).

Output requirements:
- Output ONLY the JSON object. No preamble, no trailing commentary, no markdown fences.
- The JSON must be valid and parseable in one shot.
";

var groqBody = JSON.stringify({
  model: 'llama-3.3-70b-versatile',
  messages: [{ role: 'user', content: prompt }],
  max_tokens: 3000,
  temperature: 0.85,
  response_format: { type: 'json_object' }
});

return [{
  json: {
    skip: false,
    weekRange: weekRange,
    count: picked.length,
    groqBody: groqBody
  }
}];

// Sandbox-safe: sadece tarih hesab\u0131, d\u0131\u015f request yok.
// Hedef slot: bu Pazartesi 11:00 (n8n instance local time). Ge\u00e7mi\u015fse sonraki Pzt 11:00.
var target = new Date();
target.setHours(11, 0, 0, 0);
if (target.getTime() <= Date.now() + 60 * 1000) {
  var daysUntil = (1 + 7 - target.getDay()) % 7 || 7;
  target.setDate(target.getDate() + daysUntil);
}
var windowStart = new Date(target.getTime() - 60 * 60 * 1000);
var windowEnd = new Date(target.getTime() + 60 * 60 * 1000);

var incoming = $input.first().json;

return [{
  json: Object.assign({}, incoming, {
    targetSlot: target.toISOString(),
    windowStart: windowStart.toISOString(),
    windowEnd: windowEnd.toISOString()
  })
}];

// Buffer yan\u0131t\u0131n\u0131 de\u011ferlendir ve slot dolu mu karar ver.
var resp = $input.first().json || {};
if (resp.errors) {
  throw new Error('Buffer errors: ' + JSON.stringify(resp.errors));
}

var edges = (resp.data && resp.data.posts && resp.data.posts.edges) || [];

// 'sent' = yay\u0131nland\u0131, 'error'/'failed' = i\u015flemi bitti. Di\u011ferleri (buffer/scheduled/pending/service) slot'u bloklar.
var blocking = edges.map(function(e) { return e.node; }).filter(function(n) {
  var s = (n.status || '').toLowerCase();
  return s && s !== 'sent' && s !== 'error' && s !== 'failed';
});

var slotInfo = $('Compute Slot Window').first().json;

if (blocking.length > 0) {
  return [{
    json: {
      skip: true,
      skipReason: 'Slot dolu: ' + blocking.length + ' post bu Pazartesi 11:00 penceresinde zaten schedule edilmi\u015f',
      targetSlot: slotInfo.targetSlot,
      conflicts: blocking.map(function(p) { return { id: p.id, status: p.status, dueAt: p.dueAt }; })
    }
  }];
}

// Slot bo\u015f \u2014 Prompt Generator payload'unu (groqBody dahil) passthrough et
return [{
  json: Object.assign({}, slotInfo, {
    slotCheck: {
      targetSlot: slotInfo.targetSlot,
      windowStart: slotInfo.windowStart,
      windowEnd: slotInfo.windowEnd,
      status: 'clear',
      scanned: edges.length
    }
  })
}];

var raw = ($input.first().json.choices && $input.first().json.choices[0].message.content) || '';

// Bazen JSON code fence sarmalı, temizle
var text = raw
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

var parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Groq JSON parse failed: ' + e.message + '\n--- raw ---\n' + text.substring(0, 500));
}

if (!parsed || !Array.isArray(parsed.slides) || parsed.slides.length === 0) {
  throw new Error('Invalid carousel payload: slides[] missing or empty');
}
if (!parsed.closing || !parsed.linkedinCaption || !parsed.weekRange) {
  throw new Error('Invalid carousel payload: weekRange/closing/linkedinCaption missing');
}

// carousel-server payload
var carouselBody = JSON.stringify({
  weekRange: parsed.weekRange,
  slides: parsed.slides.map(function(s) {
    return {
      emoji: String(s.emoji || '').trim() || '\ud83d\udce6',
      title: String(s.title || '').trim(),
      body: String(s.body || '').trim()
    };
  }),
  closing: String(parsed.closing).trim()
});

return [{
  json: {
    weekRange: parsed.weekRange,
    slideCount: parsed.slides.length,
    closingChars: String(parsed.closing).length,
    captionChars: String(parsed.linkedinCaption).length,
    linkedinCaption: parsed.linkedinCaption,
    carouselBody: carouselBody
  }
}];

var LINKEDIN_CHANNEL = '69bbb1fe7be9f8b1717042b1';
var QUERY = 'mutation CreatePost($input: CreatePostInput!) { createPost(input: $input) { __typename ... on PostActionSuccess { post { id status dueAt } } ... on RestProxyError { message } } }';

// Önceki node'dan: Parse Groq JSON \u2192 caption / Generate Carousel PDF \u2192 url'ler / Evaluate Slot \u2192 targetSlot
var caption = ($('Parse Groq JSON').first().json.linkedinCaption || '').trim();
var carousel = $input.first().json || {};
if (!carousel.pdfUrl || !carousel.thumbnailUrl) {
  throw new Error('carousel-server response missing pdfUrl/thumbnailUrl');
}

var slotCheck = $('Evaluate Slot').first().json.slotCheck;
if (!slotCheck || !slotCheck.targetSlot) {
  throw new Error('Slot check data missing \u2014 did Evaluate Slot node run?');
}
var dueAt = slotCheck.targetSlot;

// Buffer CreatePostInput \u2192 assets.documents = [{ url, title, thumbnailUrl }]
var bodyObj = {
  query: QUERY,
  variables: {
    input: {
      channelId: LINKEDIN_CHANNEL,
      text: caption,
      schedulingType: 'automatic',
      mode: 'customScheduled',
      dueAt: dueAt,
      assets: {
        document: {
          url: carousel.pdfUrl,
          title: carousel.title || 'Shopify Weekly Changelog',
          thumbnailUrl: carousel.thumbnailUrl
        }
      }
    }
  }
};

var bodyJson = JSON.stringify(bodyObj);

// ASCII-safe JSON (emoji surrogate pair'leri HTTP layer'da bozulmas\u0131n)
var safeBody = '';
for (var i = 0; i < bodyJson.length; i++) {
  var code = bodyJson.charCodeAt(i);
  if (code > 127) {
    safeBody += '\x5cu' + ('0000' + code.toString(16)).slice(-4);
  } else {
    safeBody += bodyJson[i];
  }
}

return [{
  json: {
    body: safeBody,
    dueAt: dueAt,
    pdfUrl: carousel.pdfUrl,
    thumbnailUrl: carousel.thumbnailUrl,
    pageCount: carousel.pageCount,
    sizeKB: carousel.sizeKB,
    captionPreview: caption.substring(0, 200)
  }
}];
